 noise(start,duration,amp){const c=this.context,b=c.createBuffer(1,c.sampleRate*duration,c.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,3);const n=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();n.buffer=b;f.type='highpass';f.frequency.value=6500;g.gain.value=amp;n.connect(f);f.connect(g);g.connect(this.musicGain);n.start(start);}
